<script>
  (function () {
    // 1. Toast Notification Helper
    const toast = document.getElementById('toast-pill');
    const toastText = document.getElementById('toast-text');
    let toastTimeout;

    function showToast(message) {
      if (!toast) return;
      toastText.textContent = message;
      toast.classList.remove('opacity-0', 'pointer-events-none');
      clearTimeout(toastTimeout);
      toastTimeout = setTimeout(() => {
        toast.classList.add('opacity-0', 'pointer-events-none');
      }, 2500);
    }

    // 2. Copy DID Micro-interaction
    const copyDidBtn = document.getElementById('copy-did-btn');
    if (copyDidBtn) {
      copyDidBtn.addEventListener('click', () => {
        const didVal = document.getElementById('did-value')?.innerText || 'did:securecert:ng:unilag:grad:2024:08194';
        navigator.clipboard?.writeText(didVal).then(() => {
          showToast('DID Copied to Clipboard');
        }).catch(() => {
          showToast('DID Copied');
        });
      });
    }

    // 3. Filter Interactive Logic
    const filterButtons = document.querySelectorAll('.filter-btn');
    const cards = document.querySelectorAll('.audit-card');

    filterButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        const category = btn.getAttribute('data-filter');

        // Toggle active button UI
        filterButtons.forEach(b => {
          b.classList.remove('bg-primary', 'text-on-primary');
          b.classList.add('bg-surface-container', 'text-on-surface-variant');
        });
        btn.classList.add('bg-primary', 'text-on-primary');
        btn.classList.remove('bg-surface-container', 'text-on-surface-variant');

        // Filter cards
        cards.forEach(card => {
          if (category === 'all' || card.getAttribute('data-category') === category) {
            card.classList.remove('hidden');
          } else {
            card.classList.add('hidden');
          }
        });
      });
    });

    // 4. Download / Export Simulation
    document.getElementById('download-jsonld-btn')?.addEventListener('click', () => {
      showToast('Generating Signed JSON-LD Digest...');
    });

    document.getElementById('export-cert-btn')?.addEventListener('click', () => {
      showToast('Preparing Lisbon Convention Seal PDF...');
    });

    // 5. Emergency Freeze Switch Logic
    const freezeToggle = document.getElementById('emergency-freeze-toggle');
    const freezeThumb = document.getElementById('freeze-thumb');
    const freezeDesc = document.getElementById('freeze-desc');
    let isFrozen = false;

    freezeToggle?.addEventListener('click', () => {
      isFrozen = !isFrozen;
      freezeToggle.setAttribute('aria-pressed', isFrozen.toString());
      if (isFrozen) {
        freezeToggle.classList.remove('bg-surface-container');
        freezeToggle.classList.add('bg-error');
        freezeThumb.classList.add('translate-x-6', 'bg-white');
        freezeThumb.classList.remove('bg-on-tertiary-container');
        if (freezeDesc) {
          freezeDesc.textContent = 'FROZEN: All outgoing verifications locked';
          freezeDesc.classList.add('text-error', 'font-medium');
        }
        showToast('Emergency Lock Armed on Ledger Node');
      } else {
        freezeToggle.classList.add('bg-surface-container');
        freezeToggle.classList.remove('bg-error');
        freezeThumb.classList.remove('translate-x-6', 'bg-white');
        freezeThumb.classList.add('bg-on-tertiary-container');
        if (freezeDesc) {
          freezeDesc.textContent = 'Active: Ledger responding to requests';
          freezeDesc.classList.remove('text-error', 'font-medium');
        }
        showToast('Ledger Unlocked & Synced');
      }
    });
  })();
